available",0,"home"],[2,1080,1440,"lantern-rooms","Preparing the space and handling bookings","busy",-1,"work"],[3,0,60,"lantern-rooms","Preparing the space and handling bookings","busy",-1,"work"],[3,60,480,"crownspire","Sleeping after the late shift","busy",2,"sleep"],[3,480,510,"crownspire","Having a meal and preparing for the day","available",0,"home"],[3,510,600,"crownspire","Taking a walk near home","available",0,"leisure"],[3,600,1080,"crownspire","Having a meal and preparing for the day","available",0,"home"],[3,1080,1440,"lantern-rooms","Preparing the space and handling bookings","busy",-1,"work"],[4,0,60,"lantern-rooms","Preparing the space and handling bookings","busy",-1,"work"],[4,60,480,"crownspire","Sleeping after the late shift","busy",2,"sleep"],[4,480,510,"crownspire","Having a meal and preparing for the day","available",0,"home"],[4,510,600,"crownspire","Making a drink and calling a friend","available",0,"leisure"],[4,600,1080,"crownspire","Having a meal and preparing for the day","available",0,"home"],[4,1080,1440,"lantern-rooms","Preparing the space and handling bookings","busy",-1,"work"],[5,0,60,"lantern-rooms","Preparing the space and handling bookings","busy",-1,"work"],[5,60,480,"crownspire","Sleeping after the late shift","busy",2,"sleep"],[5,480,510,"crownspire","Cooking and taking care of home","available",0,"home"],[5,510,600,"crownspire","Making a drink and calling a friend","available",0,"leisure"],[5,600,1440,"crownspire","Relaxing at home after errands","available",0,"home"],[6,0,540,"crownspire","Sleeping in at home","busy",2,"sleep"],[6,540,570,"crownspire","Cooking and taking care of home","available",0,"home"],[6,570,660,"crownspire","Repairing and choosing an outfit","available",0,"leisure"],[6,660,1440,"crownspire","Relaxing at home after errands","available",0,"home"]]}]'::jsonb;
begin
  select id into strict v_world from together_worlds where slug = 'vharadren' and published = true;
  if jsonb_array_length(v_payload) <> 20 then raise exception 'Expected 20 vharadren characters'; end if;
  for v_char in select value from jsonb_array_elements(v_payload) loop
    select cv.id into strict v_version
    from together_character_templates ct
    join together_character_versions cv on cv.character_template_id = ct.id and cv.version = ct.current_published_version
    join together_character_world_presence p on p.character_version_id = cv.id and p.world_id = v_world
    where ct.slug = v_char->>'slug' and ct.published = true
    limit 1;
    select count(*), count(*) filter (
      where metadata->>'source' in ('adult_cast_expansion_v1','gilded_coast_adult_cast_v1','adult_cast_schedule_v2')
    ) into v_old_count, v_owned_count
    from together_schedule_templates where character_version_id = v_version;
    if v_old_count <> v_owned_count then
      raise exception 'Refusing to replace a manually edited schedule: %', v_char->>'slug';
    end if;
    delete from together_character_schedule_events e
    using together_character_instances i
    where e.character_instance_id = i.id
      and i.character_version_id = v_version
      and e.source = 'recurring'
      and e.ends_at > now();
    delete from together_schedule_templates where character_version_id = v_version;
    for v_row in select value from jsonb_array_elements(v_char->'blocks') loop
      select id,name into strict v_location,v_location_name
      from together_locations
      where world_id = v_world and slug = v_row->>3 and owner_user_id is null;
      insert into together_schedule_templates
        (character_version_id,day_of_week,start_minute,end_minute,location_id,activity,availability,energy_delta,metadata)
      values
        (v_version,(v_row->>0)::smallint,(v_row->>1)::smallint,(v_row->>2)::smallint,
         v_location,v_row->>4,v_row->>5,(v_row->>6)::smallint,
         jsonb_build_object('source','adult_cast_schedule_v2','scheduleMode','authored',
           'userLocalClock',true,'weekIndex',0,'activityKey',v_row->>7,
           'displayLocation',v_location_name));
    end loop;
    update together_character_versions
    set life_config = jsonb_set(
      jsonb_set(
        jsonb_set(
          jsonb_set(life_config,'{workDays}',v_char->'workDays',true),
          '{occupation,workDays}',v_char->'workDays',true),
        '{occupation,activityVariants}',jsonb_build_array(v_char->>'workTask'),true),
      '{scheduling,generationVersion}',to_jsonb('adult_cast_schedule_v2'::text),true)
    where id = v_version;
  end loop;
end $repair$;
commit;
